  <AlertDialogContent>
    <AlertDialogHeader>
      <AlertDialogTitle>Delete page {pageToDelete?.num}?</AlertDialogTitle>
      <AlertDialogDescription>
        The text, images, and shapes on this page will be permanently removed. This cannot be undone.
      </AlertDialogDescription>
    </AlertDialogHeader>
    <AlertDialogFooter>
      <AlertDialogCancel>Cancel</AlertDialogCancel>
      <AlertDialogAction
        variant="destructive"
        onClick={() => pageToDelete && deleteBlankPage(pageToDelete.id)}
      >
        Delete page
      </AlertDialogAction>
    </AlertDialogFooter>
  </AlertDialogContent>
